function opts = parseInputs(varargin)
    import membrane_tracking.focused_ism.*

    p = inputParser;
    p.FunctionName = 'simulateMembraneDiffusionParticleTracking';

    % Brownian dynamics
    addParameter(p, 'rngSeed', 11);
    addParameter(p, 'nMolecules', 40);
    addParameter(p, 'moleculeConcentrationPerUm2', []);
    addParameter(p, 'boxSizeUm', [2 2]);
    addParameter(p, 'diffusionUm2PerS', 2);
    addParameter(p, 'dtS', 0.001);
    addParameter(p, 'nFrames', 1000);
    addParameter(p, 'substepsPerFrame', 5);
    addParameter(p, 'boundaryCondition', 'periodic');
    addParameter(p, 'initialPositionsUm', []);

    % Excitation and photophysics. excitationRatePerW is an effective
    % single-molecule excitation attempt rate at the beam center.
    addParameter(p, 'laserPowerW', 1e-5);
    addParameter(p, 'excitationRatePerW', 5e11);
    addParameter(p, 'saturationRateS', 5e7);
    addParameter(p, 'quantumYield', 0.70);
    addParameter(p, 'collectionEfficiency', 0.8);
    addParameter(p, 'detectorQuantumEfficiency', 0.60);
    addParameter(p, 'illuminationMode', 'gaussian');
    addParameter(p, 'laserWaistUm', 0.30);
    addParameter(p, 'initialOnFraction', 1.0);
    addParameter(p, 'blinkOffRateS', 0);
    addParameter(p, 'blinkOnRateS', 0);
    addParameter(p, 'bleachProbabilityPerAbsorbedPhoton', 0);

    % Focused ISM detector and image formation. detectorPitchUm and
    % detectorFillRatio are sample-equivalent values after magnification.
    % pixelSizeUm/detectorSizePx are retained only for legacy option
    % compatibility and are not used by the focused-ISM forward model.
    addParameter(p, 'pixelSizeUm', 0.10);
    addParameter(p, 'detectorSizePx', [96 96]);  % [rows cols]
    addParameter(p, 'detectorLayout', 'honeycomb23');
    addParameter(p, 'detectorPitchUm', 0.18);
    addParameter(p, 'detectorFillRatio', 1.0);
    addParameter(p, 'detectorSubsamples', 5);
    addParameter(p, 'psfSigmaUm', 0.14);
    addParameter(p, 'backgroundPhotonsPerPixelS', 15);
    addParameter(p, 'darkCountsPerPixelS', 2);
    addParameter(p, 'backgroundPhotonsPerDetectorS', []);
    addParameter(p, 'darkCountsPerDetectorS', []);

    % Localization
    addParameter(p, 'fitWindowRadiusPx', []);
    addParameter(p, 'detectionThresholdSigma', 5);
    addParameter(p, 'peakThresholdCounts', []);
    addParameter(p, 'minPeakSeparationPx', []);
    addParameter(p, 'minPhotonsPerLocalization', 30);
    addParameter(p, 'maxFitOffsetPx', 3);
    addParameter(p, 'minExpectedCount', 1e-9);
    addParameter(p, 'maxLocalizationsPerFrame', Inf);
    addParameter(p, 'localizationMethod', 'jointISMPoissonBayes');
    addParameter(p, 'maxEmittersPerFitRegion', 6);
    addParameter(p, 'maxLocalizationRadiusUm', []);
    addParameter(p, 'multiEmitterGroupingRadiusPx', []);
    addParameter(p, 'minResolvedEmitterSeparationPx', 0.5);
    addParameter(p, 'emitterCountPriorConcentrationPerUm2', []);
    addParameter(p, ...
        'minEmitterCountPosteriorProbabilityForDiffusion', 0.70);
    addParameter(p, 'emitterSeparationMode', 'none');
    addParameter(p, 'seedExclusionRadiusPx', []);
    addParameter(p, 'maxConsecutiveFitFailures', 2);

    % Tracking and diffusion estimation
    addParameter(p, 'trackingMaxStepUm', []);
    addParameter(p, 'trackingMethod', 'jpda');
    addParameter(p, 'trackingPriorDiffusionUm2PerS', 0.20);
    addParameter(p, 'maxGapFrames', 3);  % Number of missing frames allowed
    addParameter(p, 'minTrackLength', 8);
    addParameter(p, 'maxMsdLag', 5);
    addParameter(p, 'maxMsdFitLag', 3);
    addParameter(p, 'minMsdPairs', 3);
    addParameter(p, 'associationDetectionProbability', 0.95);
    addParameter(p, 'associationClutterRatePerFrame', 0.05);
    addParameter(p, 'associationGateChi2', 13.8155);
    addParameter(p, 'maxAssociationHypotheses', 5000);
    addParameter(p, 'minAssociationProbabilityForDiffusion', 0.75);
    addParameter(p, 'gateCensoringCorrection', true);
    addParameter(p, 'gateAcceptanceQuadraturePoints', 64);
    addParameter(p, 'nTrackingRefinementIterations', 3);
    addParameter(p, 'trackingRefinementTolerance', 0.02);
    addParameter(p, 'crbCorrectionScale', 1.0);

    % Experimental finite beta-Bernoulli raw-count trajectory sampler.
    % This is opt-in because single-time bridge updates are not validated at
    % high density and can be computationally expensive.
    addParameter(p, 'runExperimentalBnpSampler', false);
    addParameter(p, 'bnpPoolSize', []);
    addParameter(p, 'bnpMaximumPoolSize', 64);
    addParameter(p, 'bnpBurnInSweeps', 200);
    addParameter(p, 'bnpPosteriorSweeps', 200);
    addParameter(p, 'bnpFreezeDiffusionBurnFraction', 0.5);
    addParameter(p, 'bnpSeed', []);
    addParameter(p, 'bnpInitialDiffusionUm2PerS', []);
    addParameter(p, 'bnpBetaPriorA', 1);
    addParameter(p, 'bnpBetaPriorB', 1);
    addParameter(p, 'bnpDiffusionPriorShape', 1e-3);
    addParameter(p, 'bnpDiffusionPriorScale', 1e-6);
    addParameter(p, 'bnpLogNuisanceProposalSigma', 0.05);
    addParameter(p, 'bnpLogBrightnessPriorSigma', 0.20);
    addParameter(p, 'bnpBrightnessMode', 'fixed');
    addParameter(p, 'bnpCalibratedBrightnessScale', 1.0);
    addParameter(p, 'bnpBrightnessCalibrationRelativeStd', 0.05);
    addParameter(p, 'bnpInFocusPhotonThreshold', []);
    addParameter(p, 'bnpMinimumCountDecisionProbability', 0.70);
    addParameter(p, 'bnpMinimumCountEffectiveSampleSize', 30);
    addParameter(p, 'bnpMaximumCountSplitRhat', 1.10);
    addParameter(p, 'bnpMinimumInformativeSteps', 5);
    addParameter(p, 'bnpMinimumEffectiveSampleSize', 30);
    addParameter(p, 'bnpMaximumSplitRhat', 1.10);
    addParameter(p, 'bnpMaximumValidatedDensityPerUm2', 2.0);
    addParameter(p, 'bnpEnforceLegacyDensityLimit', false);

    % Output
    addParameter(p, 'makeFigure', true);
    addParameter(p, 'saveFigures', false);
    addParameter(p, 'writeOutputs', false);
    addParameter(p, 'saveMovieStack', false);
    addParameter(p, 'storePhotonEvents', true);
    addParameter(p, 'outputDir', '');
    addParameter(p, 'verbose', true);

    parse(p, varargin{:});
    opts = p.Results;

    if ~isempty(opts.rngSeed)
        opts.rngSeed = roundScalar(opts.rngSeed, 'rngSeed', 0);
    end
    opts.boxSizeUm = validatePair(opts.boxSizeUm, 'boxSizeUm');
    opts.detectorSizePx = validateIntegerPair(opts.detectorSizePx, ...
        'detectorSizePx');
    if any(opts.detectorSizePx < 8)
        error('simulateMembraneDiffusionParticleTracking:BadOption', ...
            'Each detectorSizePx dimension must be at least 8 pixels.');
    end
    opts.nMolecules = roundScalar(opts.nMolecules, 'nMolecules', 1);
    if ~isempty(opts.moleculeConcentrationPerUm2)
        opts.moleculeConcentrationPerUm2 = validateScalar( ...
            opts.moleculeConcentrationPerUm2, ...
            'moleculeConcentrationPerUm2', 0, false);
        opts.nMolecules = max(1, round(opts.moleculeConcentrationPerUm2 * ...
            prod(opts.boxSizeUm)));
    end
    opts.actualMoleculeConcentrationPerUm2 = opts.nMolecules / ...
        prod(opts.boxSizeUm);
    opts.nFrames = roundScalar(opts.nFrames, 'nFrames', 1);
    opts.substepsPerFrame = roundScalar(opts.substepsPerFrame, ...
        'substepsPerFrame', 1);
    opts.detectorSubsamples = roundScalar(opts.detectorSubsamples, ...
        'detectorSubsamples', 1);
    opts.maxGapFrames = roundScalar(opts.maxGapFrames, 'maxGapFrames', 0);
    opts.minTrackLength = roundScalar(opts.minTrackLength, ...
        'minTrackLength', 2);
    opts.maxMsdLag = roundScalar(opts.maxMsdLag, 'maxMsdLag', 1);
    opts.maxMsdFitLag = roundScalar(opts.maxMsdFitLag, ...
        'maxMsdFitLag', 1);
    opts.maxMsdFitLag = min(opts.maxMsdFitLag, opts.maxMsdLag);
    opts.minMsdPairs = roundScalar(opts.minMsdPairs, 'minMsdPairs', 1);
    opts.maxEmittersPerFitRegion = roundScalar( ...
        opts.maxEmittersPerFitRegion, 'maxEmittersPerFitRegion', 1);
    opts.maxAssociationHypotheses = roundScalar( ...
        opts.maxAssociationHypotheses, 'maxAssociationHypotheses', 10);

    opts.diffusionUm2PerS = validateScalar(opts.diffusionUm2PerS, ...
        'diffusionUm2PerS', 0, true);
    opts.dtS = validateScalar(opts.dtS, 'dtS', 0, false);
    opts.laserPowerW = validateScalar(opts.laserPowerW, ...
        'laserPowerW', 0, true);
    opts.excitationRatePerW = validateScalar(opts.excitationRatePerW, ...
        'excitationRatePerW', 0, true);
    opts.saturationRateS = validateScalar(opts.saturationRateS, ...
        'saturationRateS', 0, false);
    opts.quantumYield = validateProbability(opts.quantumYield, ...
        'quantumYield');
    opts.collectionEfficiency = validateProbability( ...
        opts.collectionEfficiency, 'collectionEfficiency');
    opts.detectorQuantumEfficiency = validateProbability( ...
        opts.detectorQuantumEfficiency, 'detectorQuantumEfficiency');
    opts.initialOnFraction = validateProbability(opts.initialOnFraction, ...
        'initialOnFraction');
    opts.blinkOffRateS = validateScalar(opts.blinkOffRateS, ...
        'blinkOffRateS', 0, true);
    opts.blinkOnRateS = validateScalar(opts.blinkOnRateS, ...
        'blinkOnRateS', 0, true);
    opts.bleachProbabilityPerAbsorbedPhoton = validateProbability( ...
        opts.bleachProbabilityPerAbsorbedPhoton, ...
        'bleachProbabilityPerAbsorbedPhoton');
    opts.laserWaistUm = validateScalar(opts.laserWaistUm, ...
        'laserWaistUm', 0, false);
    opts.pixelSizeUm = validateScalar(opts.pixelSizeUm, ...
        'pixelSizeUm', 0, false);
    opts.detectorPitchUm = validateScalar(opts.detectorPitchUm, ...
        'detectorPitchUm', 0, false);
    opts.detectorFillRatio = validateScalar(opts.detectorFillRatio, ...
        'detectorFillRatio', 0, false);
    if opts.detectorFillRatio > 1
        error('simulateMembraneDiffusionParticleTracking:BadOption', ...
            'detectorFillRatio must not exceed 1.');
    end
    opts.psfSigmaUm = validateScalar(opts.psfSigmaUm, ...
        'psfSigmaUm', 0, false);
    if ~isempty(opts.backgroundPhotonsPerDetectorS)
        opts.backgroundPhotonsPerPixelS = ...
            opts.backgroundPhotonsPerDetectorS;
    end
    if ~isempty(opts.darkCountsPerDetectorS)
        opts.darkCountsPerPixelS = opts.darkCountsPerDetectorS;
    end
    opts.backgroundPhotonsPerPixelS = validateScalar( ...
        opts.backgroundPhotonsPerPixelS, ...
        'backgroundPhotonsPerPixelS', 0, true);
    opts.darkCountsPerPixelS = validateScalar(opts.darkCountsPerPixelS, ...
        'darkCountsPerPixelS', 0, true);
    opts.backgroundPhotonsPerDetectorS = ...
        opts.backgroundPhotonsPerPixelS;
    opts.darkCountsPerDetectorS = opts.darkCountsPerPixelS;
    opts.detectionThresholdSigma = validateScalar( ...
        opts.detectionThresholdSigma, 'detectionThresholdSigma', 0, true);
    opts.minPhotonsPerLocalization = validateScalar( ...
        opts.minPhotonsPerLocalization, 'minPhotonsPerLocalization', 0, true);
    opts.maxFitOffsetPx = validateScalar(opts.maxFitOffsetPx, ...
        'maxFitOffsetPx', 0, false);
    opts.minExpectedCount = validateScalar(opts.minExpectedCount, ...
        'minExpectedCount', 0, false);
    opts.minResolvedEmitterSeparationPx = validateScalar( ...
        opts.minResolvedEmitterSeparationPx, ...
        'minResolvedEmitterSeparationPx', 0, false);
    opts.emitterSeparationMode = normalizeChoice( ...
        opts.emitterSeparationMode, {'none', 'soft', 'hard'}, ...
        'emitterSeparationMode');
    if isempty(opts.seedExclusionRadiusPx)
        opts.seedExclusionRadiusPx = ...
            opts.minResolvedEmitterSeparationPx;
    else
        opts.seedExclusionRadiusPx = validateScalar( ...
            opts.seedExclusionRadiusPx, 'seedExclusionRadiusPx', 0, false);
    end
    opts.maxConsecutiveFitFailures = roundScalar( ...
        opts.maxConsecutiveFitFailures, 'maxConsecutiveFitFailures', 0);
    opts.gateCensoringCorrection = validateLogicalScalar( ...
        opts.gateCensoringCorrection, 'gateCensoringCorrection');
    opts.gateAcceptanceQuadraturePoints = roundScalar( ...
        opts.gateAcceptanceQuadraturePoints, ...
        'gateAcceptanceQuadraturePoints', 16);
    opts.nTrackingRefinementIterations = roundScalar( ...
        opts.nTrackingRefinementIterations, ...
        'nTrackingRefinementIterations', 1);
    opts.trackingRefinementTolerance = validateScalar( ...
        opts.trackingRefinementTolerance, ...
        'trackingRefinementTolerance', 0, false);
    opts.crbCorrectionScale = validateScalar(opts.crbCorrectionScale, ...
        'crbCorrectionScale', 0, true);
    opts.runExperimentalBnpSampler = validateLogicalScalar( ...
        opts.runExperimentalBnpSampler, 'runExperimentalBnpSampler');
    opts.bnpMaximumPoolSize = roundScalar(opts.bnpMaximumPoolSize, ...
        'bnpMaximumPoolSize', 2);
    opts.bnpBurnInSweeps = roundScalar(opts.bnpBurnInSweeps, ...
        'bnpBurnInSweeps', 0);
    opts.bnpPosteriorSweeps = roundScalar(opts.bnpPosteriorSweeps, ...
        'bnpPosteriorSweeps', 4);
    opts.bnpMinimumInformativeSteps = roundScalar( ...
        opts.bnpMinimumInformativeSteps, 'bnpMinimumInformativeSteps', 1);
    opts.bnpFreezeDiffusionBurnFraction = validateProbability( ...
        opts.bnpFreezeDiffusionBurnFraction, ...
        'bnpFreezeDiffusionBurnFraction');
    opts.bnpBetaPriorA = validateScalar(opts.bnpBetaPriorA, ...
        'bnpBetaPriorA', 0, false);
    opts.bnpBetaPriorB = validateScalar(opts.bnpBetaPriorB, ...
        'bnpBetaPriorB', 0, false);
    opts.bnpDiffusionPriorShape = validateScalar( ...
        opts.bnpDiffusionPriorShape, 'bnpDiffusionPriorShape', 0, false);
    opts.bnpDiffusionPriorScale = validateScalar( ...
        opts.bnpDiffusionPriorScale, 'bnpDiffusionPriorScale', 0, false);
    opts.bnpLogNuisanceProposalSigma = validateScalar( ...
        opts.bnpLogNuisanceProposalSigma, ...
        'bnpLogNuisanceProposalSigma', 0, false);
    opts.bnpLogBrightnessPriorSigma = validateScalar( ...
        opts.bnpLogBrightnessPriorSigma, ...
        'bnpLogBrightnessPriorSigma', 0, false);
    opts.bnpBrightnessMode = normalizeChoice(opts.bnpBrightnessMode, ...
        {'fixed', 'calibrated', 'free'}, 'bnpBrightnessMode');
    opts.bnpCalibratedBrightnessScale = validateScalar( ...
        opts.bnpCalibratedBrightnessScale, ...
        'bnpCalibratedBrightnessScale', 0, false);
    opts.bnpBrightnessCalibrationRelativeStd = validateScalar( ...
        opts.bnpBrightnessCalibrationRelativeStd, ...
        'bnpBrightnessCalibrationRelativeStd', 0, true);
    if strcmp(opts.bnpBrightnessMode, 'calibrated') && ...
            opts.bnpBrightnessCalibrationRelativeStd <= 0
        error('simulateMembraneDiffusionParticleTracking:BadOption', ...
            ['bnpBrightnessCalibrationRelativeStd must be positive ' ...
            'when bnpBrightnessMode is calibrated.']);
    end
    if isempty(opts.bnpInFocusPhotonThreshold)
        opts.bnpInFocusPhotonThreshold = ...
            opts.minPhotonsPerLocalization;
    else
        opts.bnpInFocusPhotonThreshold = validateScalar( ...
            opts.bnpInFocusPhotonThreshold, ...
            'bnpInFocusPhotonThreshold', 0, true);
    end
    opts.bnpMinimumCountDecisionProbability = validateProbability( ...
        opts.bnpMinimumCountDecisionProbability, ...
        'bnpMinimumCountDecisionProbability');
    opts.bnpMinimumCountEffectiveSampleSize = validateScalar( ...
        opts.bnpMinimumCountEffectiveSampleSize, ...
        'bnpMinimumCountEffectiveSampleSize', 0, true);
    opts.bnpMaximumCountSplitRhat = validateScalar( ...
        opts.bnpMaximumCountSplitRhat, ...
        'bnpMaximumCountSplitRhat', 1, true);
    opts.bnpMinimumEffectiveSampleSize = validateScalar( ...
        opts.bnpMinimumEffectiveSampleSize, ...
        'bnpMinimumEffectiveSampleSize', 0, true);
    opts.bnpMaximumSplitRhat = validateScalar(opts.bnpMaximumSplitRhat, ...
        'bnpMaximumSplitRhat', 1, true);
    opts.bnpMaximumValidatedDensityPerUm2 = validateScalar( ...
        opts.bnpMaximumValidatedDensityPerUm2, ...
        'bnpMaximumValidatedDensityPerUm2', 0, false);
    opts.bnpEnforceLegacyDensityLimit = validateLogicalScalar( ...
        opts.bnpEnforceLegacyDensityLimit, ...
        'bnpEnforceLegacyDensityLimit');
    if ~isempty(opts.bnpSeed)
        opts.bnpSeed = roundScalar(opts.bnpSeed, 'bnpSeed', 0);
    elseif isempty(opts.rngSeed)
        opts.bnpSeed = 1;
    else
        opts.bnpSeed = opts.rngSeed + 1;
    end
    if ~isempty(opts.bnpInitialDiffusionUm2PerS)
        opts.bnpInitialDiffusionUm2PerS = validateScalar( ...
            opts.bnpInitialDiffusionUm2PerS, ...
            'bnpInitialDiffusionUm2PerS', 0, false);
    end
    if isempty(opts.maxLocalizationRadiusUm)
        opts.maxLocalizationRadiusUm = min(2 * opts.laserWaistUm, ...
            0.5 * min(opts.boxSizeUm));
    else
        opts.maxLocalizationRadiusUm = validateScalar( ...
            opts.maxLocalizationRadiusUm, ...
            'maxLocalizationRadiusUm', 0, false);
    end
    if isempty(opts.bnpPoolSize)
        expectedInModelDisc = opts.actualMoleculeConcentrationPerUm2 * ...
            pi * opts.maxLocalizationRadiusUm^2;
        opts.bnpPoolSize = max([8, opts.nMolecules + 8, ...
            ceil(2 * expectedInModelDisc + 4)]);
    else
        opts.bnpPoolSize = roundScalar(opts.bnpPoolSize, ...
            'bnpPoolSize', 1);
    end
    opts.bnpPoolSize = min(opts.bnpPoolSize,opts.bnpMaximumPoolSize);
    opts.associationDetectionProbability = validateProbability( ...
        opts.associationDetectionProbability, ...
        'associationDetectionProbability');
    if opts.associationDetectionProbability <= 0 || ...
            opts.associationDetectionProbability >= 1
        error('simulateMembraneDiffusionParticleTracking:BadOption', ...
            'associationDetectionProbability must lie strictly between 0 and 1.');
    end
    opts.associationClutterRatePerFrame = validateScalar( ...
        opts.associationClutterRatePerFrame, ...
        'associationClutterRatePerFrame', 0, false);
    opts.associationGateChi2 = validateScalar(opts.associationGateChi2, ...
        'associationGateChi2', 0, false);
    opts.minAssociationProbabilityForDiffusion = validateProbability( ...
        opts.minAssociationProbabilityForDiffusion, ...
        'minAssociationProbabilityForDiffusion');
    opts.minEmitterCountPosteriorProbabilityForDiffusion = ...
        validateProbability( ...
        opts.minEmitterCountPosteriorProbabilityForDiffusion, ...
        'minEmitterCountPosteriorProbabilityForDiffusion');
    opts.trackingPriorDiffusionUm2PerS = validateScalar( ...
        opts.trackingPriorDiffusionUm2PerS, ...
        'trackingPriorDiffusionUm2PerS', 0, true);
    if ~isempty(opts.emitterCountPriorConcentrationPerUm2)
        opts.emitterCountPriorConcentrationPerUm2 = validateScalar( ...
            opts.emitterCountPriorConcentrationPerUm2, ...
            'emitterCountPriorConcentrationPerUm2', 0, false);
    else
        opts.emitterCountPriorConcentrationPerUm2 = ...
            opts.actualMoleculeConcentrationPerUm2;
    end
    if ~isempty(opts.peakThresholdCounts)
        opts.peakThresholdCounts = validateScalar(opts.peakThresholdCounts, ...
            'peakThresholdCounts', 0, true);
    end
    if isnumeric(opts.maxLocalizationsPerFrame) && ...
            isscalar(opts.maxLocalizationsPerFrame) && ...
            isreal(opts.maxLocalizationsPerFrame) && ...
            isinf(opts.maxLocalizationsPerFrame) && ...
            opts.maxLocalizationsPerFrame > 0
        opts.maxLocalizationsPerFrame = Inf;
    else
        opts.maxLocalizationsPerFrame = roundScalar( ...
            opts.maxLocalizationsPerFrame, ...
            'maxLocalizationsPerFrame', 1);
    end

    logicalNames = {'makeFigure', 'saveFigures', 'writeOutputs', ...
        'saveMovieStack', 'storePhotonEvents', 'verbose'};
    for k = 1:numel(logicalNames)
        name = logicalNames{k};
        opts.(name) = validateLogicalScalar(opts.(name), name);
    end

    if isempty(opts.fitWindowRadiusPx)
        largestRadius = floor((min(opts.detectorSizePx) - 1) / 2);
        opts.fitWindowRadiusPx = min(max(3, ...
            ceil(4 * opts.psfSigmaUm / opts.pixelSizeUm)), largestRadius);
    else
        opts.fitWindowRadiusPx = roundScalar(opts.fitWindowRadiusPx, ...
            'fitWindowRadiusPx', 1);
        if 2 * opts.fitWindowRadiusPx + 1 > min(opts.detectorSizePx)
            error('simulateMembraneDiffusionParticleTracking:BadOption', ...
                ['fitWindowRadiusPx is too large for detectorSizePx; ' ...
                'the full fit window must fit on the detector.']);
        end
    end
    if opts.maxFitOffsetPx > opts.fitWindowRadiusPx
        error('simulateMembraneDiffusionParticleTracking:BadOption', ...
            'maxFitOffsetPx must not exceed fitWindowRadiusPx.');
    end

    if isempty(opts.minPeakSeparationPx)
        opts.minPeakSeparationPx = max(2, round(1.5 * ...
            opts.psfSigmaUm / opts.pixelSizeUm));
    else
        opts.minPeakSeparationPx = roundScalar(opts.minPeakSeparationPx, ...
            'minPeakSeparationPx', 1);
    end
    if isempty(opts.multiEmitterGroupingRadiusPx)
        opts.multiEmitterGroupingRadiusPx = max(2, ...
            ceil(4 * opts.psfSigmaUm / opts.pixelSizeUm));
    else
        opts.multiEmitterGroupingRadiusPx = roundScalar( ...
            opts.multiEmitterGroupingRadiusPx, ...
            'multiEmitterGroupingRadiusPx', 1);
    end

    opts.configuredTrackingPriorDiffusionUm2PerS = ...
        opts.trackingPriorDiffusionUm2PerS;
    if isempty(opts.trackingMaxStepUm)
        opts.trackingMaxStepUmAuto = true;
        brownianRmsStep = sqrt(4 * ...
            opts.trackingPriorDiffusionUm2PerS * opts.dtS);
        opts.trackingMaxStepUm = max(4 * brownianRmsStep, ...
            0.5 * opts.detectorPitchUm);
    else
        opts.trackingMaxStepUmAuto = false;
        opts.trackingMaxStepUm = validateScalar(opts.trackingMaxStepUm, ...
            'trackingMaxStepUm', 0, false);
    end

    outputDirIsEmpty = isempty(opts.outputDir) || ...
        (isstring(opts.outputDir) && isscalar(opts.outputDir) && ...
        strlength(opts.outputDir) == 0);
    if outputDirIsEmpty
        projectDirectory = fileparts(fileparts(fileparts( ...
            mfilename('fullpath'))));
        opts.outputDir = fullfile(projectDirectory, ...
            'output_matlab', 'membrane_diffusion_tracking');
    elseif ~(ischar(opts.outputDir) || ...
            (isstring(opts.outputDir) && isscalar(opts.outputDir)))
        error('simulateMembraneDiffusionParticleTracking:BadOption', ...
            'outputDir must be a character vector or scalar string.');
    else
        opts.outputDir = char(opts.outputDir);
    end

    opts.boundaryCondition = normalizeChoice(opts.boundaryCondition, ...
        {'reflecting', 'periodic'}, 'boundaryCondition');
    opts.illuminationMode = normalizeChoice(opts.illuminationMode, ...
        {'gaussian', 'uniform'}, 'illuminationMode');
    opts.localizationMethod = normalizeChoice(opts.localizationMethod, ...
        {'jointISMPoissonBayes'}, 'localizationMethod');
    opts.trackingMethod = normalizeChoice(opts.trackingMethod, ...
        {'jpda', 'nearestNeighbor'}, 'trackingMethod');
    opts.detectorLayout = normalizeChoice(opts.detectorLayout, ...
        {'honeycomb23', 'honeycomb93', 'square25'}, 'detectorLayout');
end
